"""Create user-requested sample TDS documents for SMART design activities."""
from pathlib import Path
from docx import Document
from docx.shared import Inches,Pt,RGBColor
OUT=Path('apps/web/public/delivery/tds');OUT.mkdir(parents=True,exist_ok=True)
DESIGNS={
2:('Ticket relationship navigation','Connect related tickets without losing workspace context.', ['Open the relationship picker from the ticket toolbar. Focus the search input and show the source ticket identifier.','Search only tickets accessible in the active workspace. Display identifier, title and relationship type for each match.','Select a result and confirm once. Reject self-links and duplicate relationships. Keep the dialog open when saving fails.','Render the saved relationship as an identifiable link. Allow keyboard-accessible removal and preserve a return path to the source ticket.'], ['Search pending: show a loading status without discarding the query.','No matches: show No matching tickets and retain editable search text.','Access revoked: hide private content, reject the save and explain that the ticket is unavailable.']),
8:('Upload recovery interactions','Help users recover interrupted uploads with clear actions and preserved context.', ['Show filename, confirmed progress and Cancel during upload.','On connection loss show Upload interrupted with Retry upload and Cancel. Offer Resume only when the backend confirms continuation support.','On expired authorization show Sign in to continue. Revalidate access before retrying.','When local bytes are unavailable ask the user to select the file again. Validate identity before continuing a previous transfer.','Cancellation invalidates queued retries and ignores late progress or completion callbacks.'], ['Interrupted: retain the filename and last confirmed progress.','Authorization required: never loop automatic retries.','File unavailable: Choose file opens the native picker; Cancel keeps the upload cancelled.','Completed: replace recovery controls with an attachment link only after durable server acknowledgement.']),
14:('Empty inbox guidance','Distinguish an empty inbox from filters that hide available messages.', ['After a successful unfiltered response with zero items, show You are all caught up and New work will appear here.','For a successful filtered response with zero matches, show No matching messages and a Clear filters button.','Clear filters resets only the active inbox filters and preserves workspace and other saved views.','Keep the previous result visible during background revalidation. Announce the new count after the request finishes.'], ['Loading: show Loading messages rather than an empty success state.','Request failure: show Unable to load messages with Retry.','After filter reset: show returned messages, or the unfiltered empty state if still empty.']),
20:('Flexible workflow entry','Allow scoped work to start at the appropriate stage with explicit inputs.', ['Let the owner choose Plan, Design, Build, Test, Deploy or Maintain independently of ticket status.','Show the selected stage, requested outcome and input references in the ticket.','Require the inputs relevant to the chosen work: a test request names a build and specification; a release request references implementation and regression evidence.','Preserve a single ticket across stages unless a new independently owned outcome requires a separate ticket.'], ['Missing input: retain the chosen stage and list the specific missing document.','Stage changed: append an Activity record without changing acceptance status.','Run completed: keep the ticket open until its acceptance criteria are reviewed.']),
7:('Upload interruption recovery','Coordinate recovery interaction, implementation and verification within one delivery ticket.', ['Preserve upload identity and confirmed progress when supported by the server.','Use distinct controls for retry, authorization and file reselection as defined by the recovery state model.','Serialize requests so repeated clicks cannot create duplicate retries.','After cancellation, ignore stale callbacks and retain a visible cancelled state.','Finalize one attachment only after the server confirms persistence.'], ['Repeated interruption: retain context and allow a new explicit retry.','Unknown continuation capability: offer a restart rather than claiming byte-offset resume.','Workspace changed: revalidate the target and never silently attach to another ticket.']),
15:('Accessible ticket titles','Make ticket titles readable and editable using keyboard and assistive technology.', ['The reading state exposes one ticket title and a clearly labelled edit action.','Activating Edit title opens a labelled text input with the current title selected.','Save persists the new value and returns focus to the title control. Cancel retains the previous value and returns focus to the same place.','Reject an empty or whitespace-only title with an associated validation message. Preserve the entered text after a failed save.','At narrow widths, wrap the title and keep the edit action reachable.'], ['Saving: prevent duplicate submission and announce the pending state.','Validation failure: keep focus in the input and announce the error.','Remote update while editing: do not overwrite the local draft silently; require reconciliation.'])}
for number,(title,purpose,requirements,states) in DESIGNS.items():
 d=Document();sec=d.sections[0];sec.page_width=Inches(8.27);sec.page_height=Inches(11.69)
 sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.8)
 normal=d.styles['Normal'];normal.font.name='Arial';normal.font.size=Pt(10);normal.paragraph_format.space_after=Pt(7)
 for name in ('Title','Heading 1','Heading 2'):d.styles[name].font.name='Arial';d.styles[name].font.color.rgb=RGBColor(0,0,0)
 sec.header.paragraphs[0].text='WORKPAL  /  FUNCTIONAL DESIGN'
 d.add_heading(title,0);d.add_paragraph(f'TDS-SMART-{number}   |   Version 1.0   |   22 November 2026')
 d.add_heading('Purpose and scope',1);d.add_paragraph(purpose)
 d.add_paragraph('Audience: product, design, engineering and QA. This specification defines the user-facing behavior and the acceptance cases for the ticket.')
 d.add_heading('Functional behavior',1)
 for i,r in enumerate(requirements,1):d.add_paragraph(f'FR-{i:02d}  {r}')
 d.add_heading('States and recovery',1)
 for r in states:d.add_paragraph(r,style='List Bullet')
 d.add_page_break();d.add_heading('Interaction and acceptance',0)
 d.add_heading('Keyboard and accessibility',1)
 d.add_paragraph('All primary actions use labelled native controls. Tab follows the visual order. Enter and Space activate buttons once. Escape dismisses a dialog without applying unsaved changes and returns focus to its trigger. Errors are associated with the relevant control; status announcements do not repeatedly interrupt the user.')
 d.add_heading('Responsive layout',1)
 d.add_paragraph('Use Workpal neutral surfaces and existing typography. At 390 px, text wraps inside the content area and actions remain visible without hover or horizontal scrolling. Loading and error content must not cover an actionable control.')
 d.add_heading('Acceptance cases',1)
 for r in ['Complete the main flow using only the keyboard and verify the persisted outcome.','Exercise each error state above and verify that the corresponding recovery action is available.','Cancel an in-progress interaction and verify that no late callback applies an unwanted change.','Repeat the flow at 390 px and verify that labels, content and actions remain accessible.','Check a workspace switch or revoked access and verify that private ticket content is not leaked.']:d.add_paragraph(r,style='List Bullet')
 d.add_heading('Handoff',1);d.add_paragraph(f'Ticket: SMART-{number}. Engineering uses FR identifiers to reference implementation work. QA records expected and actual outcomes for each acceptance case. Review comments and revised document versions remain on the originating Activity.')
 sec.footer.paragraphs[0].text=f'Workpal  |  TDS-SMART-{number}  |  1.0'
 d.core_properties.title=title;d.core_properties.subject=f'SMART-{number} functional design';d.core_properties.comments='User-authorized sample design document for product demonstration; not evidence of real execution or acceptance.'
 d.save(OUT/f'TDS-SMART-{number}.docx')
 print(OUT/f'TDS-SMART-{number}.docx')
